// components/Categories.js
import { useEffect, useState } from "react";

export default function Categories({ onSelectCategory }) {
    const [categories, setCategories] = useState([]);
    const [name, setName] = useState("");
    const [description, setDescription] = useState("");
    const [error, setError] = useState("");
    const [success, setSuccess] = useState("");

    const fetchCategories = async () => {
        try {
            const res = await fetch("http://localhost:5000/api/categories");
            const data = await res.json();
            if (!res.ok) throw new Error(data.message || "Помилка при завантаженні категорій");
            setCategories(data);
        } catch (err) {
            console.error(err);
            setError(err.message || "Помилка при завантаженні категорій");
        }
    };

    useEffect(() => {
        fetchCategories();
    }, []);

    const handleAddCategory = async (e) => {
        e.preventDefault();
        if (!name.trim()) return;

        try {
            const res = await fetch("http://localhost:5000/api/categories", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name, description })
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.message || "Помилка при створенні категорії");

            setSuccess("Категорію створено!");
            setName("");
            setDescription("");
            fetchCategories(); // оновлюємо список
        } catch (err) {
            console.error(err);
            setError(err.message || "Помилка при створенні категорії");
        }
    };

    return (
        <div className="space-y-4">
            <h2 className="text-xl font-bold mb-2">Категорії</h2>

            {error && (
                <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded-lg">
                    <p className="text-red-700 text-sm">{error}</p>
                </div>
            )}

            {success && (
                <div className="p-3 bg-green-50 border-l-4 border-green-500 rounded-lg">
                    <p className="text-green-700 text-sm">{success}</p>
                </div>
            )}

            {/* Форма додавання категорії */}
            <form onSubmit={handleAddCategory} className="space-y-2 p-3 bg-white rounded-lg shadow">
                <input
                    type="text"
                    placeholder="Назва категорії"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full p-2 border border-gray-300 rounded-lg"
                    required
                />
                <input
                    type="text"
                    placeholder="Опис категорії"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    className="w-full p-2 border border-gray-300 rounded-lg"
                />
                <button
                    type="submit"
                    className="w-full bg-blue-500 text-white p-2 rounded-lg hover:bg-blue-600 transition"
                >
                    Додати категорію
                </button>
            </form>

            {/* Список категорій */}
            <div className="space-y-2">
                {categories.map(cat => (
                    <div
                        key={cat.id}
                        onClick={() => onSelectCategory(cat.id)}
                        className="p-3 bg-white rounded-lg shadow cursor-pointer hover:bg-blue-50 transition"
                    >
                        <p className="font-semibold">{cat.name}</p>
                        <p className="text-gray-500 text-sm">{cat.description}</p>
                    </div>
                ))}
            </div>
        </div>
    );
}
